SELECT 'production' AS domain,SUM(CASE WHEN planned_quantity<=0 OR produced_quantity<0 OR actual_end<actual_start THEN 1 ELSE 0 END) AS quality_issue_rows FROM {{ ref('stg_production_orders') }} UNION ALL SELECT 'inventory',SUM(CASE WHEN on_hand_quantity<0 OR allocated_quantity<0 OR allocated_quantity>on_hand_quantity THEN 1 ELSE 0 END) FROM {{ ref('stg_inventory_snapshots') }} UNION ALL SELECT 'quality',SUM(CASE WHEN failed_quantity<0 OR failed_quantity>inspected_quantity THEN 1 ELSE 0 END) FROM {{ ref('stg_quality_inspections') }}
